function maximumBeauty(nums, k) {
  nums.sort((a, b) => a - b);
  let best = 0;
  let left = 0;
  for (let right = 0; right < nums.length; right++) {
    while (nums[right] - nums[left] > 2 * k) {
      left++;
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}

