function maximumBeauty(nums, k) {
  // Try every common value the elements could be moved to and count who can reach it.
  let best = 0;
  const low = Math.min(...nums) - k;
  const high = Math.max(...nums) + k;
  for (let value = low; value <= high; value++) {
    let count = 0;
    for (const v of nums) if (Math.abs(v - value) <= k) count++;
    best = Math.max(best, count);
  }
  return best;
}

