    const n = 2000;
    const nums = Array.from({ length: n }, () => Math.floor(rand() * 100001));
    // Skew k toward small values so the answer is usually well below n.
    const k = Math.floor(rand() ** 3 * 100001);
    return [nums, k];
  }
  const n = 1 + Math.floor(rand() * 9);
  const top = rand() < 0.5 ? 6 : 25;
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (top + 1)));
  const k = rand() < 0.2 ? 0 : Math.floor(rand() * 7);
  return [nums, k];
}
